/**
 * Reusable legal-page content and layout.
 *
 * This is plain-language operational copy for the public site. It should be
 * reviewed by qualified counsel before publication in a specific market.
 *
 * @package Insightistic_Marketing
 */

if ( ! defined( 'ABSPATH' ) ) {
	exit;
}

/** Return an escaped internal legal link. */
function insightistic_legal_link( $path, $label ) {
	return '<a href="' . esc_url( home_url( '/' . trim( $path, '/' ) . '/' ) ) . '">' . esc_html( $label ) . '</a>';
}

/**
 * Default legal document body. Keep service-specific facts conservative and
 * point account/billing questions to the app boundary or legal contact.
 */
function insightistic_legal_document( $slug ) {
	$details = insightistic_business_details();
	$email   = '<a href="mailto:' . esc_attr( antispambot( $details['email'] ) ) . '">' . esc_html( $details['email'] ) . '</a>';
	$privacy = insightistic_legal_link( 'privacy-policy', 'Privacy Policy' );
	$terms   = insightistic_legal_link( 'terms', 'Terms of Service' );

	$documents = array(
		'privacy-policy' => '<h2>Who this policy is for</h2><p>This Privacy Policy explains how ' . esc_html( $details['legal_name'] ) . ' ("WordPressistic," "we," "us") handles information when you visit Insightistic, use the public website, contact us, or use the Insightistic application.</p><h2>Information we may handle</h2><ul><li>Contact details and messages you choose to send through a form or email.</li><li>Account, workspace and subscription information handled by the Insightistic app and its payment providers.</li><li>WordPress, WooCommerce, analytics and site-health data that an authorised customer chooses to connect for the service.</li><li>Technical information such as browser, device, approximate region, referring page and security events needed to operate and protect the site.</li></ul><h2>How we use information</h2><p>We use information to provide and improve Insightistic, respond to support requests, send requested product communications, maintain security, measure site performance, meet legal obligations and prevent abuse. We do not need payment-card numbers in the WordPress connector for the analytics workflow.</p><h2>Service providers and international processing</h2><p>We may use hosting, email, analytics, support, authentication and payment providers to operate the service. The relevant providers and purposes are described in our ' . insightistic_legal_link( 'subprocessors', 'Subprocessors' ) . ' page. Processing may occur in countries outside your own, subject to applicable safeguards.</p><h2>Choices and rights</h2><p>Depending on where you live, you may have rights to access, correct, delete, export or restrict certain personal information, and to object to some processing. Contact ' . $email . ' and include enough information for us to understand your request. We may need to verify the request and may retain limited information where the law permits or requires it.</p><h2>Retention and security</h2><p>We retain information for as long as needed for the purpose collected, the customer relationship, legitimate business records, dispute handling and legal obligations. We use reasonable administrative, technical and organisational safeguards; no internet service can promise absolute security. See our ' . insightistic_legal_link( 'security', 'Security & Trust Center' ) . ' for the current public control summary.</p><h2>Children</h2><p>Insightistic is intended for business users and is not directed to children. Please contact us if you believe a child has provided personal information.</p><h2>Changes and contact</h2><p>We may update this policy as the service changes. The effective date shown above identifies the current published version. Questions can be sent to ' . $email . '.</p>',

		'terms' => '<h2>Agreement and service boundary</h2><p>These Terms of Service govern access to the Insightistic public website and application provided by ' . esc_html( $details['legal_name'] ) . '. The marketing site, the Insightistic app/API, connected WordPress sites and third-party payment services are separate service surfaces. Your use of an app or third-party service may also be governed by its own terms.</p><h2>Accounts and authorised use</h2><p>You are responsible for accurate account information, keeping credentials confidential, and ensuring that people who connect a site or view reports are authorised to do so. Do not share credentials, bypass access controls, probe another customer workspace, or use Insightistic to violate applicable law or another party’s rights.</p><h2>Connected data</h2><p>You authorise Insightistic to process the site and business data you connect for the features you select. You are responsible for having the notices, permissions and lawful basis required for your customers, employees and other people whose information may be present in that data. Review the ' . $privacy . ' and ' . insightistic_legal_link( 'data-processing', 'Data Processing Information' ) . ' pages for the current data boundary.</p><h2>Trials, plans and billing</h2><p>Available plans, prices, trial periods, renewal terms and taxes are shown in the applicable checkout or app flow at the time of signup. Billing is handled through the payment surface identified in that flow. Cancellation and refund rules are described in our ' . insightistic_legal_link( 'refunds', 'Refund & Cancellation Policy' ) . '.</p><h2>Intellectual property</h2><p>Insightistic, its software, brand assets and original content are owned by or licensed to ' . esc_html( $details['legal_name'] ) . '. You retain rights in data and content you provide, subject to the limited licence needed to operate the service. Feedback may be used to improve the service without transferring your underlying confidential information.</p><h2>Availability and changes</h2><p>We work to keep the service useful and maintained, but availability may change because of maintenance, dependencies, security work or events outside our control. We may change, suspend or retire features with reasonable notice where practical.</p><h2>Disclaimers and liability</h2><p>Insightistic provides analytics and workflow information, not legal, tax, accounting, investment, security or other professional advice. You remain responsible for business decisions and for reviewing outputs before acting on them. To the extent permitted by law, the service is provided without warranties beyond those that cannot legally be excluded, and any liability limits or remedies are governed by the applicable agreement and law.</p><h2>Contact</h2><p>Questions about these terms can be sent to ' . $email . '.</p>',

		'cookies' => '<h2>What cookies are</h2><p>Cookies and similar technologies are small files or signals used to remember preferences, support sessions, understand site usage and protect forms. Insightistic aims to keep the public marketing site lightweight and does not use cookies for a purpose that is not described here.</p><h2>Categories</h2><ul><li><strong>Strictly necessary:</strong> security, session, load-balancing or preference functions needed for a requested feature.</li><li><strong>Analytics:</strong> aggregated measurement of page performance and content usefulness, where enabled and permitted.</li><li><strong>Preference:</strong> settings such as a billing-period selection or accessibility preference.</li></ul><h2>Managing cookies</h2><p>Your browser can block or delete cookies, although some account or form features may stop working. Where consent controls are required, available non-essential technologies should remain disabled until you make a choice. The exact cookies can vary as the site and providers change; contact ' . $email . ' if you need a current cookie inventory for a review.</p><h2>Related information</h2><p>See the ' . $privacy . ' for broader information handling, and the ' . $terms . ' for service terms.</p>',

		'data-processing' => '<h2>Controller and processor roles</h2><p>For information WordPressistic collects for its own account, support, security and marketing purposes, WordPressistic LLC generally acts as the controller or business responsible for that processing. When a customer uses Insightistic to process connected business data on the customer’s instructions, the customer may act as controller and WordPressistic may act as processor or service provider, depending on applicable law and the relationship.</p><h2>Processing instructions</h2><p>Insightistic processes connected data to provide analytics, reporting, synchronisation, support and security features selected by the customer. The customer is responsible for configuring the connection lawfully, limiting access, and avoiding data that is not needed for the selected feature.</p><h2>Data subject requests</h2><p>Customers should route requests from people whose information is in connected data to the relevant customer first. We will provide reasonable assistance available through the service and may require the customer to confirm authority before acting.</p><h2>Subprocessors and safeguards</h2><p>Current service categories are listed on our ' . insightistic_legal_link( 'subprocessors', 'Subprocessors' ) . ' page. We use contractual, technical or organisational safeguards appropriate to the service and applicable requirements. International transfer details should be agreed in the customer’s contract or data processing addendum where required.</p><h2>Deletion and return</h2><p>When a customer closes an account or requests deletion, data is handled according to the account workflow, applicable retention requirements and legitimate backup/security needs. A customer that needs a signed DPA or a specific deletion/return commitment should contact ' . $email . ' before connecting regulated or sensitive data.</p>',

		'security' => '<h2>Security overview</h2><p>Insightistic is designed as a separate public marketing site, SaaS application/API and WordPress connection layer. This page describes the public control model and is not a certification, penetration-test report or guarantee.</p><h2>Data minimisation</h2><p>The connector is intended to send the business data needed for selected analytics and reporting features. Payment-card details are not required for the WordPress analytics workflow. Customers should review the fields and integrations they enable.</p><h2>Access and account controls</h2><p>Access is scoped to the account, workspace, connected site and role. Customers should use unique credentials, least privilege and multi-factor authentication where available. Administrative actions and support changes should be reviewable through the application’s audit controls.</p><h2>Transport and storage</h2><p>Connections should use HTTPS and authenticated requests. Secrets belong in protected configuration and should not be placed in public page content, browser code or support messages. Retention and deletion follow the applicable account and privacy terms.</p><h2>Reporting a vulnerability</h2><p>Please report a suspected security issue privately to ' . $email . ' with the affected URL, a concise description and safe reproduction details. Do not include passwords, payment details or unnecessary personal data. We may ask for additional information so we can investigate responsibly.</p><h2>Trust documents</h2><p>For data handling, see our ' . $privacy . ' and ' . insightistic_legal_link( 'data-processing', 'Data Processing Information' ) . '. For the current list of service categories, see ' . insightistic_legal_link( 'subprocessors', 'Subprocessors' ) . '.</p>',

		'accessibility' => '<h2>Our commitment</h2><p>We want the Insightistic marketing site and product information to be usable by people with different abilities and assistive technologies. We build with semantic HTML, keyboard-visible focus, readable contrast, responsive layouts and reduced-motion preferences in mind.</p><h2>Known limitations</h2><p>Some content or third-party surfaces may not yet meet every accessibility need. The application and checkout are separate surfaces and may have their own accessibility work and support options.</p><h2>Feedback and assistance</h2><p>If you encounter a barrier, email ' . $email . ' with the page URL, what you were trying to do, and the assistive technology or browser involved if you are comfortable sharing it. We will use the report to improve the experience and can provide information in an alternative format where practical.</p>',

		'refunds' => '<h2>Where billing is handled</h2><p>Insightistic account billing is handled through the checkout or app flow identified when you subscribe. The applicable price, trial, renewal and tax details are shown there before confirmation. The marketing website does not itself store payment-card numbers.</p><h2>Cancellation</h2><p>You can request cancellation through the account or billing controls made available to you, or contact ' . $email . ' if you cannot access them. Cancellation normally stops a future renewal; it does not automatically reverse charges already due unless the applicable terms or law provide otherwise.</p><h2>Refund requests</h2><p>If a refund or guarantee is offered for your plan, the period and conditions shown at checkout apply. Send a request promptly with the account email, plan and transaction reference. We may verify the request with the payment provider. Approved refunds are returned through the original payment method where possible.</p><h2>Service issues</h2><p>If a billing error, duplicate charge or material service issue occurs, contact us so we can investigate with the relevant provider. Do not email full payment-card details.</p>',

		'acceptable-use' => '<h2>Allowed use</h2><p>Use Insightistic to understand and improve websites, stores, campaigns and business operations that you own or are authorised to manage. Keep connected data accurate, relevant and limited to the features you use.</p><h2>Prohibited use</h2><ul><li>Illegal, fraudulent, deceptive, abusive or infringing activity.</li><li>Unauthorised access to accounts, sites, data, APIs or infrastructure.</li><li>Malware, credential theft, spam, scraping that harms the service, or attempts to defeat rate limits or security controls.</li><li>Using AI-generated insights as a substitute for professional advice or as the sole basis for a high-impact decision about a person.</li><li>Uploading sensitive data when the selected feature does not require it or when you do not have authority to process it.</li></ul><h2>Enforcement</h2><p>We may investigate activity, limit access, suspend a connection or preserve evidence when reasonably needed to protect people, customers or the service. We aim to provide notice where practical, but urgent security or legal situations may require immediate action.</p><h2>Report abuse</h2><p>Send suspected abuse or a security concern to ' . $email . ' with the relevant account, URL and facts. Do not send secrets or unnecessary personal data.</p>',

		'subprocessors' => '<h2>How to read this list</h2><p>This page lists categories of providers that may process information to operate Insightistic. The exact providers enabled for an account can depend on the feature, region, plan and integration. We do not use this page to claim that every provider processes data for every customer.</p><h2>Service categories</h2><dl><dt><strong>Hosting and infrastructure</strong></dt><dd>Application, database, storage, backups, monitoring and security infrastructure.</dd><dt><strong>Authentication and account services</strong></dt><dd>Sign-in, session, account recovery and access-control support.</dd><dt><strong>Payments and billing</strong></dt><dd>Checkout, subscription, tax, invoicing and payment-status processing through the provider shown at checkout.</dd><dt><strong>Email and support</strong></dt><dd>Transactional messages, product updates and customer support communications.</dd><dt><strong>Analytics and diagnostics</strong></dt><dd>Aggregated product or website diagnostics where enabled for the relevant feature and permitted by the customer.</dd></dl><h2>Questions and changes</h2><p>We may update this page when providers or processing purposes change. Customers that need a provider-level list for a contract review should contact ' . $email . ' with the account and region. See the ' . $privacy . ' and ' . $terms . ' for the governing information.</p>',

		'legal-notices' => '<h2>Operator</h2><p>Insightistic is a product of <strong>' . esc_html( $details['legal_name'] ) . '</strong>.</p><address>' . esc_html( $details['address'] ) . '<br>' . esc_html( $details['city'] . ', ' . $details['state'] . ' ' . $details['postal_code'] ) . '<br>' . esc_html( $details['country'] ) . '</address><p>Entity ID: <strong>' . esc_html( $details['entity_id'] ) . '</strong><br>Reference: <strong>' . esc_html( $details['reference'] ) . '</strong><br>Email: ' . $email . '</p><h2>Brand and content</h2><p>Insightistic, WordPressistic and related product names, logos and content belong to their respective owners. Do not reuse brand assets or imply endorsement without written permission.</p><h2>Legal requests</h2><p>For notices, privacy questions, accessibility barriers, security reports or billing questions, email ' . $email . ' and identify the subject clearly. This page is a public contact notice and does not replace a formal service agreement or legal advice.</p>',
	);

	$document = isset( $documents[ $slug ] ) ? $documents[ $slug ] : '';
	return apply_filters( 'insightistic_legal_document', $document, $slug );
}

/** Render the shared legal layout used by every legal page template. */
function insightistic_render_legal_page( $slug, $fallback_title, $eyebrow = 'Legal & trust' ) {
	$title = insightistic_current_title() ? insightistic_current_title() : $fallback_title;
	$details = insightistic_business_details();
	?>
	<section class="ins-section ins-legal-hero">
		<div class="ins-container ins-narrow">
			<?php insightistic_breadcrumbs(); ?>
			<p class="ins-eyebrow"><?php echo esc_html( $eyebrow ); ?></p>
			<h1 class="ins-page-title"><?php echo esc_html( $title ); ?></h1>
			<p class="ins-legal__updated"><?php esc_html_e( 'Last updated:', 'insightistic-marketing' ); ?> <?php echo esc_html( insightistic_legal_updated_date() ); ?></p>
			<div class="ins-legal__identity" aria-label="<?php esc_attr_e( 'Legal entity', 'insightistic-marketing' ); ?>">
				<span class="ins-logo__dot" aria-hidden="true"></span>
				<div><strong><?php echo esc_html( $details['brand'] ); ?></strong><span><?php esc_html_e( 'A product of WordPressistic LLC under the WPISTIC EcoSystem', 'insightistic-marketing' ); ?></span><address><?php echo esc_html( $details['address'] ); ?><br><?php echo esc_html( $details['city'] . ', ' . $details['state'] . ' ' . $details['postal_code'] . ( 'US' === $details['country'] ? ', USA' : ', ' . $details['country'] ) ); ?></address></div>
			</div>
		</div>
	</section>
	<section class="ins-section ins-legal-content">
		<div class="ins-container ins-narrow ins-prose">
			<?php echo wp_kses_post( insightistic_legal_document( $slug ) ); // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped -- curated theme document. ?>
		</div>
	</section>
	<?php
}
